// ──────────────────────────── tests ──────────────────────────────────────

test('an ordinary search matches by substring', () => {
  withDb((db) => {
    eq(findUsers(db, 'Ada').map((r) => r.name), ['Ada', 'Adam']);
  });
});

test('a search that matches nothing returns nothing', () => {
  withDb((db) => {
    eq(findUsers(db, 'zzz'), []);
  });
});

test("a term with a quote is data, not code — it matches no one", () => {
  withDb((db) => {
    // classic injection: close the string, OR a always-true clause
    eq(findUsers(db, "' OR 1=1 --"), []);
  });
});

test('a term with a quote cannot leak the admin row', () => {
  withDb((db) => {
    const names = findUsers(db, "xyz' OR role='admin' --").map((r) => r.name);
    eq(names.includes('Root'), false);
  });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a plain comment renders as-is', () => {
  eq(
    renderComment({ author: 'Ada', body: 'nice post' }),
    '<li><b>Ada</b>: nice post</li>'
  );
});

test('angle brackets in the body are escaped to entities', () => {
  eq(
    renderComment({ author: 'Ada', body: 'hi <3' }),
    '<li><b>Ada</b>: hi &lt;3</li>'
  );
});

test('a script tag in the body cannot survive as a tag', () => {
  const html = renderComment({ author: 'Mallory', body: '<script>steal()</script>' });
  ok(!html.includes('<script>'), 'the literal <script> tag must not appear');
  ok(html.includes('&lt;script&gt;'), 'it must be escaped instead');
});

test('a hostile author name is escaped too', () => {
  const html = renderComment({ author: '<img src=x onerror=hack>', body: 'hi' });
  ok(!html.includes('<img'), 'the author is user input as well');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a plain filename resolves inside the base dir', () => {
  eq(safeJoin('/srv/files', 'report.pdf'), '/srv/files/report.pdf');
});

test('a nested path inside the base dir is fine', () => {
  eq(safeJoin('/srv/files', 'reports/q1.pdf'), '/srv/files/reports/q1.pdf');
});

test('climbing out with ../ is refused', () => {
  throws(() => safeJoin('/srv/files', '../../etc/passwd'), 'outside');
});

test('an absolute user path cannot jump to the filesystem root', () => {
  throws(() => safeJoin('/srv/files', '/etc/passwd'), 'outside');
});

test('a sneaky path that climbs then re-enters is still refused', () => {
  throws(() => safeJoin('/srv/files', 'reports/../../secret'), 'outside');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the owner can read their own invoice', () => {
  const store = makeStore();
  eq(getInvoice(store, 'ada', 'inv-1').cents, 12000);
});

test('a stranger cannot read an invoice they do not own', () => {
  const store = makeStore();
  throws(() => getInvoice(store, 'mallory', 'inv-1'), 'not found');
});

test('one user cannot read another real user\'s invoice', () => {
  const store = makeStore();
  throws(() => getInvoice(store, 'ada', 'inv-2'), 'not found');
});

test('an unknown id and a not-yours id fail identically', () => {
  const store = makeStore();
  let unknown, notYours;
  try { getInvoice(store, 'ada', 'inv-999'); } catch (e) { unknown = e.message; }
  try { getInvoice(store, 'ada', 'inv-2'); } catch (e) { notYours = e.message; }
  eq(unknown.replace('inv-999', 'ID'), notYours.replace('inv-2', 'ID'));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a token is a long hex string', () => {
  const tok = makeResetToken();
  ok(/^[0-9a-f]{32,}$/.test(tok), `expected 32+ hex chars, got ${tok}`);
});

test('1000 tokens are all distinct', () => {
  const seen = new Set();
  for (let i = 0; i < 1000; i++) seen.add(makeResetToken());
  ok(seen.size === 1000, 'every token must be unique');
});

test('consecutive tokens are not adjacent values', () => {
  // if token N+1 is predictable from token N, this catches it
  const a = BigInt('0x' + makeResetToken());
  const b = BigInt('0x' + makeResetToken());
  const gap = a > b ? a - b : b - a;
  ok(gap > 1n << 64n, 'consecutive tokens must be astronomically far apart');
});

test('tokens carry real entropy (many distinct leading bytes)', () => {
  const firstBytes = new Set();
  for (let i = 0; i < 200; i++) firstBytes.add(makeResetToken().slice(0, 2));
  ok(firstBytes.size > 50, `expected varied prefixes, saw ${firstBytes.size}`);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a name change is applied', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada L.' }).name, 'Ada L.');
});

test('name and email can both be edited', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada L.', email: 'ada@x.com' });
  eq(out.name, 'Ada L.');
  eq(out.email, 'ada@x.com');
});

test('a smuggled role is ignored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada', role: 'admin' }).role, 'user');
});

test('id and balance cannot be overwritten from the patch', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user', balance: 0 };
  const out = updateProfile(user, { id: 999, balance: 1000000 });
  eq(out.id, 1);
  eq(out.balance, 0);
});

test('an unknown field in the patch is dropped, not stored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada', isAdmin: true });
  eq('isAdmin' in out, false);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a plain in-site path is kept', () => {
  eq(safeRedirect('/dashboard'), '/dashboard');
});

test('an in-site path keeps its query string', () => {
  eq(safeRedirect('/orders?page=2'), '/orders?page=2');
});

test('a missing next falls back to the home page', () => {
  eq(safeRedirect(undefined), '/');
  eq(safeRedirect(''), '/');
});

test('an absolute URL to another site is refused', () => {
  eq(safeRedirect('https://evil.test/pwn'), '/');
});

test('a protocol-relative URL is refused', () => {
  eq(safeRedirect('//evil.test/pwn'), '/');
});

test('a backslash-smuggled host is refused', () => {
  eq(safeRedirect('/\\evil.test/pwn'), '/');
});

test('a javascript: destination is refused', () => {
  eq(safeRedirect('javascript:alert(document.cookie)'), '/');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('accepts a single tag', () => {
  eq(isValidTagList('js'), true);
});

test('accepts a comma-separated list, spaces optional', () => {
  eq(isValidTagList('js,node'), true);
  eq(isValidTagList('js, node, sql'), true);
});

test('rejects an empty list and a non-letter tag', () => {
  eq(isValidTagList(''), false);
  eq(isValidTagList('js, 42'), false);
});

test('rejects a trailing comma', () => {
  eq(isValidTagList('js, node,'), false);
});

test('rejects a long malformed list without hanging', () => {
  const attack = 'a'.repeat(26) + '!';
  const started = performance.now();
  eq(isValidTagList(attack), false);
  const elapsed = performance.now() - started;
  ok(elapsed < 150, `took ${elapsed.toFixed(0)}ms — should be sub-millisecond`);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('keeps the operational fields', () => {
  const line = logLine(request());
  eq(line.method, 'POST');
  eq(line.path, '/api/checkout');
  eq(line.status, 201);
  eq(line.durationMs, 42);
  eq(line.userId, 'u_1042');
});

test('drops a top-level password field', () => {
  ok(!('password' in logLine(request())));
});

test('does not log the Authorization header or the session cookie', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('sk_live_9f3c1d'), 'bearer token reached the log');
  ok(!text.includes('8c4e2a1b'), 'session cookie reached the log');
});

test('does not log anything from the request body', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('4111111111111111'), 'card number reached the log');
  ok(!text.includes('ada@example.com'), 'customer e-mail reached the log');
});

test('the line has exactly the five allowed fields', () => {
  eq(Object.keys(logLine(request())).sort(), [
    'durationMs',
    'method',
    'path',
    'status',
    'userId',
  ]);
});

