// ─────────────────────────────────────────────────────────────────────────
//  05 · password-reset tokens you can guess                  ★★☆ core
//  concepts: security · CSPRNG · unguessable tokens
//  run: node 05-predictable-token.js
// ─────────────────────────────────────────────────────────────────────────
//
//  makeResetToken() mints the secret in a password-reset link. Whoever
//  holds the token can reset the account, so it must be UNGUESSABLE: no
//  two ever equal, and knowing one tells you nothing about the next.
//  Shape: a long hex string.
//
//      makeResetToken()  → 'a3f9…' (32 hex chars, unpredictable)
//
//  An attacker requested one reset for their own account, saw the
//  token's pattern, and walked it to other users' tokens.
//
//  The code below is fully written — and a security hole. 3 tests fail:
//  they check the tokens are long and unpredictable. Find the flaw and
//  fix it with the smallest change. Keep makeResetToken()'s signature.
//
//  hint: "random enough to look shuffled" and "random enough that an
//  attacker cannot predict it" are different bars. What does this
//  generator use as its source of surprise, and could you reproduce its
//  output if you knew the starting state?

import { test, ok } from '../../_lib/check.js';

let counter = 1000;

export function makeResetToken() {
  counter += 1;
  return `reset-${counter.toString(16)}`;
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a token is a long hex string', () => {
  const tok = makeResetToken();
  ok(/^[0-9a-f]{32,}$/.test(tok), `expected 32+ hex chars, got ${tok}`);
});

test('1000 tokens are all distinct', () => {
  const seen = new Set();
  for (let i = 0; i < 1000; i++) seen.add(makeResetToken());
  ok(seen.size === 1000, 'every token must be unique');
});

test('consecutive tokens are not adjacent values', () => {
  // if token N+1 is predictable from token N, this catches it
  const a = BigInt('0x' + makeResetToken());
  const b = BigInt('0x' + makeResetToken());
  const gap = a > b ? a - b : b - a;
  ok(gap > 1n << 64n, 'consecutive tokens must be astronomically far apart');
});

test('tokens carry real entropy (many distinct leading bytes)', () => {
  const firstBytes = new Set();
  for (let i = 0; i < 200; i++) firstBytes.add(makeResetToken().slice(0, 2));
  ok(firstBytes.size > 50, `expected varied prefixes, saw ${firstBytes.size}`);
});

jstrain/26-security-hunts/05-predictable.solution:
// ─────────────────────────────────────────────────────────────────────────
//  05 · password-reset tokens you can guess — SOLUTION       ★★☆ core
//  concepts: security · CSPRNG · unguessable tokens
//  run: node 05-predictable-token.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: a predictable secret. The token was a counter in hex —
//  `reset-3e9`, `reset-3ea`, … — so seeing one reset token told an
//  attacker every other account's token. Unique is not the same as
//  unpredictable; an auto-increment id is perfectly unique and perfectly
//  guessable.
//  The tell: a security token built from a counter, a timestamp, or
//  `Math.random()`. None of those are cryptographically random —
//  Math.random in particular is seeded PRNG state an attacker can
//  recover from a few outputs.
//  The minimal fix: draw from a CSPRNG —
//      import { randomBytes } from 'node:crypto';
//      export function makeResetToken() {
//        return randomBytes(16).toString('hex'); // 128 bits, 32 hex chars
//      }
//  16 bytes = 128 bits of entropy: unique in practice AND unguessable.
//  In the wild: session ids, API keys, reset/verify links, CSRF tokens,
//  filenames meant to be unlisted. Anything a bearer of the value gets
//  to DO something with needs crypto randomness, never Math.random.

import { test, ok } from '../../_lib/check.js';
import { randomBytes } from 'node:crypto';

export function makeResetToken() {
  return randomBytes(16).toString('hex');
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a token is a long hex string', () => {
  const tok = makeResetToken();
  ok(/^[0-9a-f]{32,}$/.test(tok), `expected 32+ hex chars, got ${tok}`);
});

test('1000 tokens are all distinct', () => {
  const seen = new Set();
  for (let i = 0; i < 1000; i++) seen.add(makeResetToken());
  ok(seen.size === 1000, 'every token must be unique');
});

test('consecutive tokens are not adjacent values', () => {
  // if token N+1 is predictable from token N, this catches it
  const a = BigInt('0x' + makeResetToken());
  const b = BigInt('0x' + makeResetToken());
  const gap = a > b ? a - b : b - a;
  ok(gap > 1n << 64n, 'consecutive tokens must be astronomically far apart');
});

test('tokens carry real entropy (many distinct leading bytes)', () => {
  const firstBytes = new Set();
  for (let i = 0; i < 200; i++) firstBytes.add(makeResetToken().slice(0, 2));
  ok(firstBytes.size > 50, `expected varied prefixes, saw ${firstBytes.size}`);
});

jstrain/26-security-hunts/06-mass-assign.starter:
// ─────────────────────────────────────────────────────────────────────────
//  06 · the profile update that grants admin                 ★★★ stretch
//  concepts: security · mass assignment · field allowlists
//  run: node 06-mass-assignment.js
// ─────────────────────────────────────────────────────────────────────────
//
//  updateProfile(user, patch) applies a profile edit from a request
//  body. Users may change ONLY their display name and email. Everything
//  else — role, id, balance — is off-limits and must be ignored, even
//  when the request body includes it:
//
//      updateProfile({ id: 1, name: 'Ada', role: 'user' },
//                    { name: 'Ada L.' })
//        → { id: 1, name: 'Ada L.', role: 'user' }
//
//  Someone POSTed { "name": "x", "role": "admin" } to the profile
//  endpoint and became an admin.
//
//  The code below is fully written — and a security hole. 3 tests fail:
//  they smuggle privileged fields into the patch. Find the flaw and fix
//  it with the smallest change. Keep the legitimate edits working.
//
//  hint: the safe question is not "which fields should I block?" (you
//  will forget one) but "which fields do I ALLOW?" Where does this code
//  decide which keys of `patch` get through — and does it decide at all?

import { test, eq } from '../../_lib/check.js';

export function updateProfile(user, patch) {
  return { ...user, ...patch };
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a name change is applied', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada L.' }).name, 'Ada L.');
});

test('name and email can both be edited', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada L.', email: 'ada@x.com' });
  eq(out.name, 'Ada L.');
  eq(out.email, 'ada@x.com');
});

test('a smuggled role is ignored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada', role: 'admin' }).role, 'user');
});

test('id and balance cannot be overwritten from the patch', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user', balance: 0 };
  const out = updateProfile(user, { id: 999, balance: 1000000 });
  eq(out.id, 1);
  eq(out.balance, 0);
});

test('an unknown field in the patch is dropped, not stored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada', isAdmin: true });
  eq('isAdmin' in out, false);
});

