// ─────────────────────────────────────────────────────────────────────────
//  06 · the profile update that grants admin — SOLUTION      ★★★ stretch
//  concepts: security · mass assignment · field allowlists
//  run: node 06-mass-assignment.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: mass assignment. `{ ...user, ...patch }` copies EVERY
//  key of the request body over the user, so `{ role: 'admin' }` in the
//  POST body wrote straight through to the record. The spread trusted
//  whatever the client sent.
//  The tell: a wholesale spread/merge/Object.assign of a
//  request-derived object onto a domain object. The code decided what to
//  keep by omission — and omission forgets.
//  The minimal fix: an ALLOWLIST — pull only the fields users may edit,
//  and ignore the rest by construction:
//      const EDITABLE = ['name', 'email'];
//      const safe = {};
//      for (const k of EDITABLE)
//        if (k in patch) safe[k] = patch[k];
//      return { ...user, ...safe };
//  Allowlist, never denylist: a blocklist of ['role','id','balance']
//  ships a hole the day someone adds an `isAdmin` column.
//  In the wild: Rails' original mass-assignment CVEs, `User.update(params)`,
//  ORM `.save(req.body)`, GraphQL input types wired straight to columns.
//  Bind inputs to an explicit DTO, not to your table.

import { test, eq } from '../../_lib/check.js';

const EDITABLE = ['name', 'email'];

export function updateProfile(user, patch) {
  const safe = {};
  for (const key of EDITABLE) {
    if (key in patch) safe[key] = patch[key];
  }
  return { ...user, ...safe };
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a name change is applied', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada L.' }).name, 'Ada L.');
});

test('name and email can both be edited', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada L.', email: 'ada@x.com' });
  eq(out.name, 'Ada L.');
  eq(out.email, 'ada@x.com');
});

test('a smuggled role is ignored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  eq(updateProfile(user, { name: 'Ada', role: 'admin' }).role, 'user');
});

test('id and balance cannot be overwritten from the patch', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user', balance: 0 };
  const out = updateProfile(user, { id: 999, balance: 1000000 });
  eq(out.id, 1);
  eq(out.balance, 0);
});

test('an unknown field in the patch is dropped, not stored', () => {
  const user = { id: 1, name: 'Ada', email: 'a@x.com', role: 'user' };
  const out = updateProfile(user, { name: 'Ada', isAdmin: true });
  eq('isAdmin' in out, false);
});

jstrain/26-security-hunts/07-open-redire.starter:
// ─────────────────────────────────────────────────────────────────────────
//  07 · the login that sends you somewhere else               ★★☆ core
//  concepts: security · open redirect · URL parsing
//  run: node 07-open-redirect.js
// ─────────────────────────────────────────────────────────────────────────
//
//  After login the app bounces you back to where you were, taken from
//  `?next=`. safeRedirect(next) returns a same-site destination —
//  path plus query — or '/' when the value is anything else:
//
//      safeRedirect('/orders?page=2')      → '/orders?page=2'
//      safeRedirect('https://evil.test')   → '/'
//
//  A phishing mail went out linking to the REAL login page with a
//  crafted `next`, and users who signed in landed on a clone of the
//  dashboard that asked them to "confirm" their password.
//
//  The code below is fully written — and a security hole. 3 tests fail:
//  they pass destinations that leave the site. Find the flaw and fix it
//  with the smallest change. Keep the legitimate cases working.
//
//  hint: "starts with a slash" and "stays on this site" are not the
//  same claim. A browser reads `//host` as a full URL, and a scheme
//  does not have to be spelled `http`. What would happen if you parsed
//  the value against your own origin and looked at what came out?

import { test, eq } from '../../_lib/check.js';

const SITE = 'https://app.example';

export function safeRedirect(next) {
  if (!next) return '/';
  if (next.startsWith('http')) return '/'; // no absolute URLs
  return next;
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a plain in-site path is kept', () => {
  eq(safeRedirect('/dashboard'), '/dashboard');
});

test('an in-site path keeps its query string', () => {
  eq(safeRedirect('/orders?page=2'), '/orders?page=2');
});

test('a missing next falls back to the home page', () => {
  eq(safeRedirect(undefined), '/');
  eq(safeRedirect(''), '/');
});

test('an absolute URL to another site is refused', () => {
  eq(safeRedirect('https://evil.test/pwn'), '/');
});

test('a protocol-relative URL is refused', () => {
  eq(safeRedirect('//evil.test/pwn'), '/');
});

test('a backslash-smuggled host is refused', () => {
  eq(safeRedirect('/\\evil.test/pwn'), '/');
});

test('a javascript: destination is refused', () => {
  eq(safeRedirect('javascript:alert(document.cookie)'), '/');
});

jstrain/26-security-hunts/07-open-redire.solution:
// ─────────────────────────────────────────────────────────────────────────
//  07 · the login that sends you somewhere else — SOLUTION    ★★☆ core
//  concepts: security · open redirect · URL parsing
//  run: node 07-open-redirect.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: open redirect (unvalidated redirect). The guard was a
//  denylist of one string — "does it start with http" — and a denylist
//  of one string is a hole with a lid on it. `//evil.test` is a full
//  URL to a browser (protocol-relative: it reuses the current scheme),
//  `/\evil.test` is normalised to the same thing by every browser's URL
//  parser, and `javascript:` never mentions http at all.
//  The tell: user input reaching a `Location:` header after a check
//  written as "not the bad thing" instead of "is the one good thing".
//  The minimal fix: stop pattern-matching the string and let the URL
//  parser tell you where it actually points — resolve it against your
//  own origin and refuse anything that lands elsewhere:
//      const url = new URL(next, SITE);
//      if (url.origin !== SITE) return '/';
//      return url.pathname + url.search;
//  `new URL(next, SITE)` throws on nothing a browser would accept, and
//  it collapses backslashes, `..` segments, and stray schemes for you —
//  the same normalisation the browser will do, which is the point.
//  Returning `pathname + search` instead of the raw input is the second
//  half: you now emit a value you built, not one the attacker typed.
//  In the wild: `?next=` / `?returnUrl=` / `?redirect_uri=` on login and
//  logout, OAuth callbacks (where the allowlist is mandatory and exact),
//  and "continue shopping" links. Phishing's favourite primitive,
//  because the link really does start at your real domain.

import { test, eq } from '../../_lib/check.js';

const SITE = 'https://app.example';

export function safeRedirect(next) {
  if (!next) return '/';
  let url;
  try {
    url = new URL(next, SITE);
  } catch {
    return '/';
  }
  if (url.origin !== SITE) return '/';
  return url.pathname + url.search;
}

// ──────────────────────────── tests ──────────────────────────────────────

test('a plain in-site path is kept', () => {
  eq(safeRedirect('/dashboard'), '/dashboard');
});

test('an in-site path keeps its query string', () => {
  eq(safeRedirect('/orders?page=2'), '/orders?page=2');
});

test('a missing next falls back to the home page', () => {
  eq(safeRedirect(undefined), '/');
  eq(safeRedirect(''), '/');
});

test('an absolute URL to another site is refused', () => {
  eq(safeRedirect('https://evil.test/pwn'), '/');
});

test('a protocol-relative URL is refused', () => {
  eq(safeRedirect('//evil.test/pwn'), '/');
});

test('a backslash-smuggled host is refused', () => {
  eq(safeRedirect('/\\evil.test/pwn'), '/');
});

test('a javascript: destination is refused', () => {
  eq(safeRedirect('javascript:alert(document.cookie)'), '/');
});

jstrain/26-security-hunts/08-redos.starter:
// ─────────────────────────────────────────────────────────────────────────
//  08 · the validator that stops the server                   ★★☆ core
//  concepts: security · ReDoS · catastrophic backtracking
//  run: node 08-redos.js
// ─────────────────────────────────────────────────────────────────────────
//
//  isValidTagList(input) validates the tag box on the article editor.
//  A valid list is one or more lowercase tags separated by commas,
//  with optional spaces around each comma — and nothing else:
//
//      isValidTagList('js, node, sql')  → true
//      isValidTagList('js,,node')       → false
//
//  It shipped, and one afternoon every request in the process started
//  timing out. The CPU was pinned at 100%; the event loop was not
//  blocked on I/O, it was blocked on this function, on one input,
//  from one visitor.
//
//  The code below is fully written — and a security hole. 2 tests fail:
//  one input it should reject in microseconds and does not reject in
//  any useful amount of time, and one it wrongly accepts. Find the
//  flaw and fix it with the smallest change.
//
//  hint: count the ways the regex engine can split `aaaa` between the
//  inner `+` and the outer `+`. On a string it can ALMOST match, an
//  engine that backtracks has to try every one of them before it is
//  allowed to say no — and "every one of them" doubles per character.

import { test, eq, ok } from '../../_lib/check.js';

export function isValidTagList(input) {
  return /^(\s*[a-z]+\s*,?)+$/.test(input);
}

// ──────────────────────────── tests ──────────────────────────────────────

test('accepts a single tag', () => {
  eq(isValidTagList('js'), true);
});

test('accepts a comma-separated list, spaces optional', () => {
  eq(isValidTagList('js,node'), true);
  eq(isValidTagList('js, node, sql'), true);
});

test('rejects an empty list and a non-letter tag', () => {
  eq(isValidTagList(''), false);
  eq(isValidTagList('js, 42'), false);
});

test('rejects a trailing comma', () => {
  eq(isValidTagList('js, node,'), false);
});

test('rejects a long malformed list without hanging', () => {
  const attack = 'a'.repeat(26) + '!';
  const started = performance.now();
  eq(isValidTagList(attack), false);
  const elapsed = performance.now() - started;
  ok(elapsed < 150, `took ${elapsed.toFixed(0)}ms — should be sub-millisecond`);
});

jstrain/26-security-hunts/08-redos.solution:
// ─────────────────────────────────────────────────────────────────────────
//  08 · the validator that stops the server — SOLUTION         ★★☆ core
//  concepts: security · ReDoS · catastrophic backtracking
//  run: node 08-redos.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: ReDoS — regular-expression denial of service. The
//  pattern `^(\s*[a-z]+\s*,?)+$` nests a `+` inside a `+` with the
//  comma optional, so `aaaa` can be carved up as one group of four,
//  two of two, four of one, and every arrangement in between. On a
//  string that ALMOST matches — 26 letters and then a `!` — the engine
//  must exhaust all of them before it may answer "no", and the count
//  doubles with every extra character. One 30-byte request, one pinned
//  core, one dead process: no payload, no injection, just arithmetic.
//  The tell: a quantifier applied to a group that itself ends in a
//  quantifier, with an optional separator — `(a+)+`, `(\s*\w+)*`,
//  `(\w+,?)+`. When two parts of a pattern can both claim the same
//  character, matching stops being linear.
//  The minimal fix: make the split unambiguous — one tag, then any
//  number of "comma then tag" units, with the separator REQUIRED
//  inside the repeated group:
//      return /^[a-z]+(?:\s*,\s*[a-z]+)*$/.test(input);
//  Now every character belongs to exactly one part of the pattern,
//  there is nothing to backtrack over, and the trailing comma the old
//  pattern shrugged at is rejected by construction — the same sloppiness
//  caused both failures.
//  In the wild: e-mail and URL validators copied off the internet, log
//  and user-agent parsers, markdown/HTML tag matchers — anywhere a
//  regex runs on input the user typed. Defenses beyond the rewrite:
//  cap the input length before matching, and keep validation regexes
//  boring enough to read.

import { test, eq, ok } from '../../_lib/check.js';

export function isValidTagList(input) {
  return /^[a-z]+(?:\s*,\s*[a-z]+)*$/.test(input);
}

// ──────────────────────────── tests ──────────────────────────────────────

test('accepts a single tag', () => {
  eq(isValidTagList('js'), true);
});

test('accepts a comma-separated list, spaces optional', () => {
  eq(isValidTagList('js,node'), true);
  eq(isValidTagList('js, node, sql'), true);
});

test('rejects an empty list and a non-letter tag', () => {
  eq(isValidTagList(''), false);
  eq(isValidTagList('js, 42'), false);
});

test('rejects a trailing comma', () => {
  eq(isValidTagList('js, node,'), false);
});

test('rejects a long malformed list without hanging', () => {
  const attack = 'a'.repeat(26) + '!';
  const started = performance.now();
  eq(isValidTagList(attack), false);
  const elapsed = performance.now() - started;
  ok(elapsed < 150, `took ${elapsed.toFixed(0)}ms — should be sub-millisecond`);
});

