// ─────────────────────────────────────────────────────────────────────────
//  09 · the log that stores everyone's password               ★★☆ core
//  concepts: security · sensitive data exposure · allowlisting
//  run: node 09-secrets-in-logs.js
// ─────────────────────────────────────────────────────────────────────────
//
//  logLine(req) builds the object the request logger writes for every
//  request. Logs are shipped to a third-party search tool that half the
//  company can read, so the line must contain the five operational
//  fields and NOTHING else:
//
//      method · path · status · durationMs · userId
//
//  A support engineer searching the logs for a customer's order id
//  found the customer's session cookie instead.
//
//  The code below is fully written — and a security hole. 3 tests fail:
//  they search the finished line for things that must never appear in
//  it. Find the flaw and fix it with the smallest change.
//
//  hint: the filter names the secrets it knows about. Every field added
//  to a request between now and forever is a field it has never heard
//  of. Which direction should the list point?

import { test, eq, ok } from '../../_lib/check.js';

const SECRET_KEYS = ['password', 'token'];

export function logLine(req) {
  const entry = { ...req };
  for (const key of SECRET_KEYS) delete entry[key];
  return entry;
}

// ─── a request as the framework hands it over ─────────────────────────────

const request = () => ({
  method: 'POST',
  path: '/api/checkout',
  status: 201,
  durationMs: 42,
  userId: 'u_1042',
  password: 'hunter2',
  headers: {
    authorization: 'Bearer sk_live_9f3c1d',
    cookie: 'session=8c4e2a1b',
    'user-agent': 'curl/8.4.0',
  },
  body: {
    email: 'ada@example.com',
    card: { number: '4111111111111111', cvc: '737' },
  },
});

// ──────────────────────────── tests ──────────────────────────────────────

test('keeps the operational fields', () => {
  const line = logLine(request());
  eq(line.method, 'POST');
  eq(line.path, '/api/checkout');
  eq(line.status, 201);
  eq(line.durationMs, 42);
  eq(line.userId, 'u_1042');
});

test('drops a top-level password field', () => {
  ok(!('password' in logLine(request())));
});

test('does not log the Authorization header or the session cookie', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('sk_live_9f3c1d'), 'bearer token reached the log');
  ok(!text.includes('8c4e2a1b'), 'session cookie reached the log');
});

test('does not log anything from the request body', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('4111111111111111'), 'card number reached the log');
  ok(!text.includes('ada@example.com'), 'customer e-mail reached the log');
});

test('the line has exactly the five allowed fields', () => {
  eq(Object.keys(logLine(request())).sort(), [
    'durationMs',
    'method',
    'path',
    'status',
    'userId',
  ]);
});

jstrain/26-security-hunts/09-secrets-in-.solution:
// ─────────────────────────────────────────────────────────────────────────
//  09 · the log that stores everyone's password — SOLUTION     ★★☆ core
//  concepts: security · sensitive data exposure · allowlisting
//  run: node 09-secrets-in-logs.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: sensitive data exposure through logging — and
//  underneath it, the denylist mistake. `{ ...req }` copies everything
//  the framework attached to the request and the loop then removes the
//  two secrets somebody happened to think of in 2022. `headers` and
//  `body` were never on the list, so the bearer token, the session
//  cookie, the customer's e-mail and their card number all rode along.
//  The tell: a spread of an object you did not build, followed by
//  `delete`. Copy-then-subtract keeps whatever you failed to name; the
//  set of things you failed to name grows every sprint, without a diff
//  anyone reviews.
//  The minimal fix: turn the list around. Name what may be logged and
//  build the line out of those fields only:
//      const LOGGABLE = ['method','path','status','durationMs','userId'];
//      const entry = {};
//      for (const key of LOGGABLE) if (key in req) entry[key] = req[key];
//      return entry;
//  Now a new request field defaults to invisible, which is the safe
//  default, and the `Object.keys` test becomes a real contract: adding
//  a field to the log is a deliberate edit to one array.
//  Note the shallow-copy trap too — even an allowlisted object field
//  would carry its whole subtree. Log scalars, or project nested values
//  explicitly.
//  In the wild: request loggers, error reporters (the exception object
//  holds the arguments that caused it), analytics events, and support
//  tooling that renders "the raw payload". Logs are usually the least
//  protected copy of your data and the one that lives longest.

import { test, eq, ok } from '../../_lib/check.js';

const LOGGABLE = ['method', 'path', 'status', 'durationMs', 'userId'];

export function logLine(req) {
  const entry = {};
  for (const key of LOGGABLE) {
    if (key in req) entry[key] = req[key];
  }
  return entry;
}

// ─── a request as the framework hands it over ─────────────────────────────

const request = () => ({
  method: 'POST',
  path: '/api/checkout',
  status: 201,
  durationMs: 42,
  userId: 'u_1042',
  password: 'hunter2',
  headers: {
    authorization: 'Bearer sk_live_9f3c1d',
    cookie: 'session=8c4e2a1b',
    'user-agent': 'curl/8.4.0',
  },
  body: {
    email: 'ada@example.com',
    card: { number: '4111111111111111', cvc: '737' },
  },
});

// ──────────────────────────── tests ──────────────────────────────────────

test('keeps the operational fields', () => {
  const line = logLine(request());
  eq(line.method, 'POST');
  eq(line.path, '/api/checkout');
  eq(line.status, 201);
  eq(line.durationMs, 42);
  eq(line.userId, 'u_1042');
});

test('drops a top-level password field', () => {
  ok(!('password' in logLine(request())));
});

test('does not log the Authorization header or the session cookie', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('sk_live_9f3c1d'), 'bearer token reached the log');
  ok(!text.includes('8c4e2a1b'), 'session cookie reached the log');
});

test('does not log anything from the request body', () => {
  const text = JSON.stringify(logLine(request()));
  ok(!text.includes('4111111111111111'), 'card number reached the log');
  ok(!text.includes('ada@example.com'), 'customer e-mail reached the log');
});

test('the line has exactly the five allowed fields', () => {
  eq(Object.keys(logLine(request())).sort(), [
    'durationMs',
    'method',
    'path',
    'status',
    'userId',
  ]);
});

jstrain/26-security-hunts/10-csrf-vacuou.starter:
// ─────────────────────────────────────────────────────────────────────────
//  10 · the CSRF check that checks nothing               ★★★ stretch
//  concepts: security · CSRF · vacuous comparison
//  run: node 10-csrf-vacuous-check.js
// ─────────────────────────────────────────────────────────────────────────
//
//  assertCsrf(session, request) is the middleware that stands in front
//  of every state-changing route. Safe methods pass through; anything
//  else must arrive with the token the server put in the session, or
//  the request is refused with an Error whose message contains 'csrf':
//
//      assertCsrf({ csrfToken: 'abc' }, post('abc'))  → returns
//      assertCsrf({ csrfToken: 'abc' }, post('xyz'))  → throws 'csrf'
//
//  A pen-tester filed the report: a page on their own domain, a form
//  posting to /api/transfer, no token anywhere — and the transfer went
//  through. Every test the team had written was green.
//
//  The code below is fully written — and a security hole. 2 tests fail,
//  both describing a request that carries no token at all. Find the
//  flaw and fix it with the smallest change.
//
//  hint: the check asks "are these two the same?" — and it is perfectly
//  happy when the answer is "yes, both absent". What must be true about
//  the expected value BEFORE comparing it to anything is worth asking.

import { test, eq, throws } from '../../_lib/check.js';

const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export function assertCsrf(session, request) {
  if (SAFE_METHODS.has(request.method)) return;
  if (request.body.csrfToken !== session.csrfToken) {
    throw new Error('csrf token mismatch');
  }
}

// ─── request helpers ──────────────────────────────────────────────────────

const post = (csrfToken) => ({
  method: 'POST',
  body: csrfToken === undefined ? {} : { csrfToken, amount: 500 },
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a POST carrying the session token is allowed', () => {
  eq(assertCsrf({ csrfToken: 'abc123' }, post('abc123')), undefined);
});

test('a POST carrying the wrong token is refused', () => {
  throws(() => assertCsrf({ csrfToken: 'abc123' }, post('xyz789')), 'csrf');
});

test('a POST carrying no token is refused', () => {
  throws(() => assertCsrf({ csrfToken: 'abc123' }, post(undefined)), 'csrf');
});

test('safe methods pass without a token', () => {
  eq(assertCsrf({ csrfToken: 'abc123' }, { method: 'GET', body: {} }), undefined);
  eq(assertCsrf({ csrfToken: 'abc123' }, { method: 'HEAD', body: {} }), undefined);
});

test('a session with no token yet cannot authorise anything', () => {
  throws(() => assertCsrf({}, post(undefined)), 'csrf');
});

test('two empty tokens are not a match', () => {
  throws(() => assertCsrf({ csrfToken: '' }, post('')), 'csrf');
});

jstrain/26-security-hunts/10-csrf-vacuou.solution:
// ─────────────────────────────────────────────────────────────────────────
//  10 · the CSRF check that checks nothing — SOLUTION      ★★★ stretch
//  concepts: security · CSRF · vacuous comparison
//  run: node 10-csrf-vacuous-check.js
// ─────────────────────────────────────────────────────────────────────────
//
//  Walkthrough:
//  Vulnerability: cross-site request forgery, let through by a VACUOUS
//  check — a comparison that is trivially satisfied because both sides
//  are missing. `undefined !== undefined` is false, so a request with
//  no token, hitting a session that never got one, sailed past the
//  guard. The attacker does not need to steal or guess the token; they
//  need to send NO token, to a visitor whose session has none either.
//  The tell: an equality test on two values that may both be absent,
//  with no precondition on the expected side. The same shape ships
//  bugs far beyond CSRF — `user.role === requiredRole` when both are
//  undefined, `sig === expectedSig` when the signer was skipped, any
//  `if (a !== b) reject`. A security check must assert the secret
//  EXISTS before it asserts the two match.
//  The minimal fix: validate the expected value first, then compare a
//  real string to a real string:
//      const expected = session.csrfToken;
//      const got = request.body.csrfToken;
//      if (typeof expected !== 'string' || expected === '')
//        throw new Error('csrf: session has no token');
//      if (got !== expected) throw new Error('csrf token mismatch');
//  Fail closed: no token established means no state-changing request
//  is authorised, which is also the correct answer for a logged-out or
//  expired session.
//  In production, compare with `crypto.timingSafeEqual` over equal-length
//  buffers so response time leaks nothing, and pair the token with
//  `SameSite=Lax` cookies — defence in layers, because a single check is
//  a single point of failure.
//  In the wild: hand-rolled CSRF middleware, webhook signature checks
//  where a missing header compares equal to a missing secret, and
//  feature flags where "undefined equals undefined" quietly grants
//  everyone the admin experience.

import { test, eq, throws } from '../../_lib/check.js';

const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export function assertCsrf(session, request) {
  if (SAFE_METHODS.has(request.method)) return;
  const expected = session.csrfToken;
  if (typeof expected !== 'string' || expected === '') {
    throw new Error('csrf: session has no token');
  }
  if (request.body.csrfToken !== expected) {
    throw new Error('csrf token mismatch');
  }
}

// ─── request helpers ──────────────────────────────────────────────────────

const post = (csrfToken) => ({
  method: 'POST',
  body: csrfToken === undefined ? {} : { csrfToken, amount: 500 },
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a POST carrying the session token is allowed', () => {
  eq(assertCsrf({ csrfToken: 'abc123' }, post('abc123')), undefined);
});

test('a POST carrying the wrong token is refused', () => {
  throws(() => assertCsrf({ csrfToken: 'abc123' }, post('xyz789')), 'csrf');
});

test('a POST carrying no token is refused', () => {
  throws(() => assertCsrf({ csrfToken: 'abc123' }, post(undefined)), 'csrf');
});

test('safe methods pass without a token', () => {
  eq(assertCsrf({ csrfToken: 'abc123' }, { method: 'GET', body: {} }), undefined);
  eq(assertCsrf({ csrfToken: 'abc123' }, { method: 'HEAD', body: {} }), undefined);
});

test('a session with no token yet cannot authorise anything', () => {
  throws(() => assertCsrf({}, post(undefined)), 'csrf');
});

test('two empty tokens are not a match', () => {
  throws(() => assertCsrf({ csrfToken: '' }, post('')), 'csrf');
});
